var i=`0958-japanese-gyoza`;var n=`world-0958`;var o=`JP`;var t=`east-asia`;var r=8;var s=51;var l={en:`Japanese Gyoza`,ua:`Японські ґьодза`};var g={en:`Japanese Gyoza is a Japan dish made with ground pork, napa cabbage, garlic, light soy sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Японські ґьодза, страва кухні країни Японія. Основні складники: свинячий фарш, пекінська капуста, часник, світлий соєвий соус. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-pork`,450,`g`],[`napa-cabbage`,290,`g`],[`garlic`,4,`clove`],[`ground-ginger`,16,`g`],[`light-soy-sauce`,35,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:22,i:[[`gyoza-wrappers`,35,`pcs`]]},{en:`Brown the gyoza flat bottoms in an oiled pan before adding water for covered steaming; cook the pork center thoroughly.`,ua:`Підрум’яньте плоске дно ґьодза на змащеній сковороді, потім долийте воду й пропарте під кришкою до повної готовності свинини.`,t:[`pan-frying`],m:10,i:[[`canola-oil`,38,`ml`]]},{en:`Steam the prepared portions in a covered steamer over gently boiling water for about 6 minutes until completely cooked or set, then remove carefully.`,ua:`Готуйте підготовлені порції на парі під кришкою над слабко киплячою водою близько 6 хвилин до повної готовності чи застигання, обережно вийміть.`,t:[`steaming`],m:6,i:[[`water`,130,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`rice-vinegar`,50,`ml`],[`chili-oil`,25,`ml`]]}];var c={slug:i,id:n,country:`JP`,region:t,servings:8,minutes:51,title:l,text:g,steps:d};export{o as country,c as default,n as id,s as minutes,t as region,r as servings,i as slug,d as steps,g as text,l as title};